const $=s=>document.querySelector(s);const langSelect=$('#language');
function productMarkup(p){return `<article class="product-card"><div class="product-image"><span class="tag" data-i18n="${p.category}"></span><img src="${imageBase+p.image}" alt="" loading="lazy"></div><div class="product-bottom"><h3 data-i18n="${p.name}"></h3><div class="product-meta"><div><span class="price-old">${p.old}</span> <span class="price">${p.price}</span></div><span class="stars" aria-label="5 stars"><img src="pictures/icons/star-1.svg" alt=""><img src="pictures/icons/star-2.svg" alt=""><img src="pictures/icons/star-3.svg" alt=""><img src="pictures/icons/star-4.svg" alt=""><img src="pictures/icons/star-5.svg" alt=""></span></div></div></article>`}
$('#product-grid').innerHTML=products.map(productMarkup).join('');$('#offer-grid').innerHTML=[products[3],products[4],products[1]].map(productMarkup).join('');
function setLanguage(lang){const t=text[lang]||text.uz;document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(t[key])el.innerHTML=t[key]});$('#email').placeholder=t.emailPlaceholder;localStorage.setItem('organick-language',lang)}
const stored=localStorage.getItem('organick-language');if(stored&&text[stored])langSelect.value=stored;setLanguage(langSelect.value);langSelect.addEventListener('change',e=>setLanguage(e.target.value));
const toggle=$('.menu-toggle'),nav=$('.nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',open)});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}));
$('.subscribe').addEventListener('submit',e=>{e.preventDefault();$('.form-message').textContent=text[langSelect.value].subscribeSuccess;e.currentTarget.reset()});






